import { test, expect } from '@playwright/test';

test.describe('Background Job Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display toast notification when background job completes', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Background Job' }).click();
    await page.waitForTimeout(5000); // Wait for the background job to complete
    const toast = page.getByText('Background job completed successfully');
    await expect(toast).toBeVisible();
  });

  test('should not display toast notification if job fails', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Background Job with Error' }).click();
    await page.waitForTimeout(5000); // Wait for the background job to complete
    const toast = page.getByText('Background job failed');
    await expect(toast).toBeVisible();
  });
});
